(()=>{const reduce=matchMedia('(prefers-reduced-motion:reduce)');document.querySelectorAll('.about-fleet-stats strong').forEach(el=>{const final=el.textContent,number=parseInt(final,10),suffix=final.replace(/[0-9]/g,'');let done=false,frame=0;const observer=new IntersectionObserver(entries=>{if(!entries[0].isIntersecting||done)return;done=true;observer.disconnect();if(reduce.matches)return;const start=performance.now();function tick(now){const p=Math.min(1,(now-start)/1300),value=Math.round(number*(1-Math.pow(1-p,3)));el.textContent=(final.startsWith('0')?String(value).padStart(2,'0'):value)+suffix;if(p<1)frame=requestAnimationFrame(tick)}frame=requestAnimationFrame(tick);reduce.addEventListener('change',()=>{if(reduce.matches){cancelAnimationFrame(frame);el.textContent=final}})},{threshold:.5});observer.observe(el)});const chart=document.querySelector('.expedition-chart'),ship=chart?.querySelector('.chart-vessel'),brief=document.querySelector('.expedition-brief');if(!chart||!ship||!brief)return;const ports=[...chart.querySelectorAll('.expedition-port')];ports.forEach((port,i)=>port.addEventListener('click',()=>{ports.forEach(p=>p.setAttribute('aria-pressed',String(p===port)));const c=chart.getBoundingClientRect(),r=port.getBoundingClientRect();const x=r.left-c.left+r.width/2-ship.offsetLeft-ship.offsetWidth/2,y=r.top-c.top+r.height/2-ship.offsetTop-ship.offsetHeight/2;ship.style.transform=`translate3d(${x}px,${y}px,0) rotate(${i%2?5:-5}deg)`;brief.querySelector('h2').textContent=port.querySelector('strong').textContent;brief.querySelector('.brief-copy').textContent=port.dataset.brief;brief.querySelector('a').href=`#event-${i+1}`;if(!reduce.matches)brief.animate([{opacity:.4,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:250,easing:'cubic-bezier(.23,1,.32,1)'})}));})();
